using System;
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public enum SfxId
{
    Jump,
    ProjectileFire,
    Hit,
    CrystalPickup,
    ChestOpen,
    Lose,
    Win,
    BossSpawn,
    UiClick
}

/// <summary>
/// Plays one-shot sound effects through a small pool of AudioSources.
/// Sounds that match an existing game event (crystal pickup, win, lose, boss spawn) are played from here
/// by listening to that event; the others are requested by the code that causes them via
/// <see cref="Play(SfxId)"/>. Clips are generated by Tools/GenerateSfx.py.
/// </summary>
public class AudioManager : MonoBehaviour
{
    public static AudioManager Instance { get; private set; }

    private const string MasterVolumeKey = "MasterVolume";

    [Serializable]
    public struct SfxEntry
    {
        public SfxId id;
        public AudioClip clip;
        [Range(0f, 1f)] public float volume;
        [Tooltip("Random pitch change (+/-) per play, so sounds that repeat a lot do not sound identical.")]
        [Range(0f, 0.3f)] public float pitchVariation;
        [Tooltip("Keep playing while the game is paused (menu clicks).")]
        public bool playWhenPaused;
    }

    [Header("Mix")]
    [Range(0f, 1f)]
    [SerializeField] private float _masterVolume = 1f;

    [Header("Voices")]
    [Tooltip("How many sounds can play at the same time. When all are busy the oldest one is cut.")]
    [SerializeField] private int _poolSize = 8;

    [Header("Sounds")]
    [SerializeField] private SfxEntry[] _sfx;

    [Header("Music")]
    [Tooltip("Background music loop, started when the scene starts. Leave empty for no music (the Intro Scene has none).")]
    [SerializeField] private AudioClip _music;
    [Tooltip("Music volume, multiplied by the master volume. Kept low so it stays in the background.")]
    [Range(0f, 1f)]
    [SerializeField] private float _musicVolume = 0.25f;
    [Tooltip("Seconds the music takes to fade out when the run ends, so the win/lose sound is clear.")]
    [SerializeField] private float _musicFadeOutSeconds = 0.6f;

    private AudioSource _musicSource;
    private Coroutine _musicFade;
    private AudioSource[] _sources;
    private readonly Dictionary<SfxId, SfxEntry> _lookup = new Dictionary<SfxId, SfxEntry>();
    private int _nextSource;

    /// <summary>Overall volume 0..1 for sound effects and music. Saved between sessions.</summary>
    public float MasterVolume
    {
        get => _masterVolume;
        set
        {
            _masterVolume = Mathf.Clamp01(value);
            PlayerPrefs.SetFloat(MasterVolumeKey, _masterVolume);
            PlayerPrefs.Save();
            // Not "isPlaying": while the pause menu is open the music is paused and reports false, but the volume buttons live there.
            if (_musicSource != null && _musicSource.clip != null && _musicFade == null)
                _musicSource.volume = _musicVolume * _masterVolume;
        }
    }

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }
        Instance = this;

        // The player's volume choice (from the volume buttons) wins over the default set in the Inspector.
        _masterVolume = Mathf.Clamp01(PlayerPrefs.GetFloat(MasterVolumeKey, _masterVolume));

        _sources = new AudioSource[Mathf.Max(1, _poolSize)];
        for (int i = 0; i < _sources.Length; i++)
        {
            AudioSource source = gameObject.AddComponent<AudioSource>();
            source.playOnAwake = false;
            source.spatialBlend = 0f; // plain 2D sound effects
            _sources[i] = source;
        }

        foreach (SfxEntry entry in _sfx)
            _lookup[entry.id] = entry;

        _musicSource = gameObject.AddComponent<AudioSource>();
        _musicSource.playOnAwake = false;
        _musicSource.loop = true;
        _musicSource.spatialBlend = 0f;
    }

    private void Start()
    {
        if (_music != null)
            PlayMusic();
    }

    private void OnEnable()
    {
        EventBus.Subscribe<CrystalCollectedEvent>(OnCrystalCollected);
        EventBus.Subscribe<GameStateChangedEvent>(OnGameStateChanged);
        EventBus.Subscribe<BossPhaseStartedEvent>(OnBossPhaseStarted);
    }

    private void OnDisable()
    {
        EventBus.Unsubscribe<CrystalCollectedEvent>(OnCrystalCollected);
        EventBus.Unsubscribe<GameStateChangedEvent>(OnGameStateChanged);
        EventBus.Unsubscribe<BossPhaseStartedEvent>(OnBossPhaseStarted);
    }

    private void OnDestroy()
    {
        if (Instance == this)
            Instance = null;
    }

    // ── Event hooks ───────────────────────────────────────────────────────────

    private void OnCrystalCollected(CrystalCollectedEvent e) => PlaySfx(SfxId.CrystalPickup);
    private void OnBossPhaseStarted(BossPhaseStartedEvent e) => PlaySfx(SfxId.BossSpawn);

    private void OnGameStateChanged(GameStateChangedEvent e)
    {
        if (e.State.IsRunEnded())
            FadeOutMusic();

        if (e.State == GameState.GameOver)
            PlaySfx(SfxId.Lose);
        else if (e.State == GameState.Victory)
            PlaySfx(SfxId.Win);
    }

    // ── Music ─────────────────────────────────────────────────────────────────

    public void PlayMusic()
    {
        if (_music == null || _musicSource == null) return;

        if (_musicFade != null)
        {
            StopCoroutine(_musicFade);
            _musicFade = null;
        }

        _musicSource.clip = _music;
        _musicSource.volume = _musicVolume * _masterVolume;
        _musicSource.Play();
    }

    public void FadeOutMusic()
    {
        if (_musicSource == null || !_musicSource.isPlaying || _musicFade != null) return;
        _musicFade = StartCoroutine(FadeOutMusicRoutine());
    }

    private IEnumerator FadeOutMusicRoutine()
    {
        float startVolume = _musicSource.volume;
        float duration = Mathf.Max(_musicFadeOutSeconds, 0.01f);

        // Unscaled time: the run ends with the time scale at 0.
        for (float t = 0f; t < duration; t += Time.unscaledDeltaTime)
        {
            _musicSource.volume = Mathf.Lerp(startVolume, 0f, t / duration);
            yield return null;
        }

        _musicSource.Stop();
        _musicFade = null;
    }

    // ── API ───────────────────────────────────────────────────────────────────

    /// <summary>Convenience for callers: does nothing if the scene has no AudioManager.</summary>
    public static void Play(SfxId id)
    {
        if (Instance != null)
            Instance.PlaySfx(id);
    }

    public void PlaySfx(SfxId id)
    {
        if (!_lookup.TryGetValue(id, out SfxEntry entry) || entry.clip == null) return;

        float pitch = 1f + UnityEngine.Random.Range(-entry.pitchVariation, entry.pitchVariation);
        PlaySfx(entry.clip, entry.volume, pitch, entry.playWhenPaused);
    }

    /// <param name="volume">0..1, multiplied by the master volume.</param>
    /// <param name="playWhenPaused">If true the sound is not silenced by AudioListener.pause (used while the pause menu is open).</param>
    public void PlaySfx(AudioClip clip, float volume = 1f, float pitch = 1f, bool playWhenPaused = false)
    {
        if (clip == null || _sources == null) return;

        AudioSource source = NextSource();
        source.clip = clip;
        source.volume = Mathf.Clamp01(volume) * _masterVolume;
        source.pitch = pitch;
        source.ignoreListenerPause = playWhenPaused;
        source.Play();
    }

    /// <summary>A free source if there is one, otherwise the one that has been playing the longest.</summary>
    private AudioSource NextSource()
    {
        for (int i = 0; i < _sources.Length; i++)
        {
            int index = (_nextSource + i) % _sources.Length;
            if (!_sources[index].isPlaying)
            {
                _nextSource = (index + 1) % _sources.Length;
                return _sources[index];
            }
        }

        AudioSource oldest = _sources[_nextSource];
        _nextSource = (_nextSource + 1) % _sources.Length;
        return oldest;
    }
}
